```sql
SELECT IIF(AVG(A13) > AVG(A12), '1996', '1995') AS higher_year FROM district;
```

```sql
SELECT DISTINCT T1.name, T1.id FROM sets AS T1 JOIN set_translations AS T2 ON T1.code = T2.setCode WHERE T1.block = 'Shadowmoor' AND T2.language = 'Italian' ORDER BY T1.name ASC LIMIT 2;
```

```sql
WITH TopComment AS (SELECT UserId FROM comments GROUP BY UserId ORDER BY COUNT(*) DESC LIMIT 1) SELECT B.Name FROM badges B JOIN TopComment TC ON B.UserId = TC.UserId;
```

```sql
SELECT DISTINCT T2.name FROM users AS T1 INNER JOIN badges AS T2 ON T1.Id = T2.UserId WHERE T1.Reputation = (SELECT MAX(Reputation) FROM users);
```

```sql
SELECT COUNT(*) FROM ( SELECT T2.Id FROM users AS T1 INNER JOIN posts AS T2 ON T1.Id = T2.OwnerUserId INNER JOIN votes AS T3 ON T3.PostId = T2.Id WHERE T1.DisplayName = 'Matt Parker' GROUP BY T2.Id HAVING COUNT(T3.Id) > 4);
```

```sql
SELECT Title FROM posts ORDER BY ViewCount DESC, Id ASC LIMIT 5;
```

```sql
SELECT CommentCount, AnswerCount FROM posts WHERE Title = 'Clustering 1D data';
```

```sql
SELECT COUNT(id) FROM votes WHERE BountyAmount >= 30;
```

```sql
SELECT a.attribute_name AS hero_attribute_name, ha.attribute_value AS hero_attribute_value FROM superhero s INNER JOIN hero_attribute ha ON s.id = ha.hero_id INNER JOIN attribute a ON ha.attribute_id = a.id WHERE s.superhero_name = 'Abomination';
```

```sql
SELECT COUNT(T2.driverId) FROM races  AS T1 JOIN results AS T2 ON T2.raceId = T1.raceId WHERE T1.year = 2007 AND T1.name = 'Bahrain Grand Prix' AND T2.time IS NULL;
```

```sql
SELECT ((MAX(CASE WHEN T2.raceId = 853 THEN CAST(T2.fastestLapSpeed AS REAL) END) - MAX(CASE WHEN T2.raceId = 854 THEN CAST(T2.fastestLapSpeed AS REAL) END)) * 100) / MAX(CASE WHEN T2.raceId = 853 THEN CAST(T2.fastestLapSpeed AS REAL) END) AS faster_percentage FROM drivers AS T1 INNER JOIN results AS T2 ON T2.driverId = T1.driverId WHERE T1.forename = 'Paul' AND T1.surname = 'di Resta';
```

```sql
SELECT COUNT(DISTINCT T2.year) FROM circuits AS T1 INNER JOIN races AS T2 ON T2.circuitId = T1.circuitId WHERE T1.name = 'Silverstone Circuit' AND T2.name = 'British Grand Prix';
```

```sql
SELECT CAST(COUNT(DISTINCT CASE WHEN T1.country = 'Germany' THEN T2.raceId END) AS REAL) * 100 / COUNT(DISTINCT T2.raceId) FROM circuits T1 INNER JOIN races T2 ON T2.circuitId = T1.circuitId WHERE T2.name = 'European Grand Prix';
```

```sql
SELECT T2.name FROM constructorStandings AS T1 INNER JOIN constructors AS T2 ON T1.constructorId = T2.constructorId GROUP BY T2.name ORDER BY SUM(T1.points) DESC LIMIT 1;
```

```sql
SELECT T1.name FROM races AS T1 INNER JOIN results AS T2 ON T1.raceId = T2.raceId WHERE T2.fastestLapTime = (SELECT MIN(fastestLapTime) FROM results WHERE fastestLapTime IS NOT NULL);
```

```sql
SELECT player_name FROM Player WHERE height = (SELECT MIN(height) FROM Player) ORDER BY player_name ASC;
```

```sql
SELECT DISTINCT t1.player_name FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE t2.strength = (SELECT MAX(strength) FROM Player_Attributes) ORDER BY t1.player_name ASC;
```
